-- Payroll profiles (SCRUM-567, the company payroll's R2):
-- docs/progress/plans/payroll-real-build/PLAN.md §1, "0022 payroll_profiles".
--
-- Generated by drizzle-kit from shared/schema.ts and hand-edited as 0021 is:
-- re-runnable, the public-schema qualifier stripped, parent keys before the
-- foreign keys that use them. Expand-only.
--
-- One profile per employee (the prototype's EmployeePayrollProfile), with its
-- dated allocation versions, salary advances and separate payments as child
-- rows, and the setup audit. Every child names its profile through
-- (tenant_id, profile_id), and the profile names its employee through
-- (tenant_id, employee_id) with ON DELETE RESTRICT, so payroll can never be
-- deleted from under a person and no row can point at another park group's
-- employee. employees gets the unique (tenant_id, id) that key needs.
--
-- Casual workers are outside this payroll (owner, 2026-10-20): no table here
-- points at casual_workers. Nothing is seeded; profiles are entered, or
-- proposed from HR data as `needs-review` drafts that carry no pay amount
-- until a payroll role saves them.
CREATE TABLE IF NOT EXISTS "payroll_profiles" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"employee_id" varchar NOT NULL,
	"worker_type" text NOT NULL,
	"job_title" text DEFAULT '' NOT NULL,
	"department" text,
	"monthly_salary" numeric(14, 2) DEFAULT '0' NOT NULL,
	"day_rate" numeric(14, 2) DEFAULT '0' NOT NULL,
	"fixed_fee" numeric(14, 2) DEFAULT '0' NOT NULL,
	"joined_on" date,
	"last_working_day" date,
	"tax_id" text DEFAULT '' NOT NULL,
	"sso_number" text DEFAULT '' NOT NULL,
	"sso_title" text,
	"given_name" text,
	"surname" text,
	"date_of_birth" date,
	"nationality" text,
	"passport_number" text,
	"leaving_reason" text,
	"food_allowance_eligible" boolean NOT NULL,
	"food_allowance_per_day" numeric(14, 2) DEFAULT '0' NOT NULL,
	"sso_eligible" boolean NOT NULL,
	"pnd1_eligible" boolean NOT NULL,
	"service_charge_eligible" boolean NOT NULL,
	"ot_eligible" boolean NOT NULL,
	"pnd3_withholding_percent" numeric(7, 4) DEFAULT '0' NOT NULL,
	"cash_handling_fee_percent" numeric(7, 4) DEFAULT '0' NOT NULL,
	"payment_method" text DEFAULT 'bank-transfer' NOT NULL,
	"bank_name" text DEFAULT '' NOT NULL,
	"bank_account_number" text DEFAULT '' NOT NULL,
	"bank_account_name" text DEFAULT '' NOT NULL,
	"bank_code" text,
	"bank_mobile" text,
	"bank_email" text,
	"third_party_reason" text DEFAULT '' NOT NULL,
	"student_loan_monthly" numeric(14, 2) DEFAULT '0' NOT NULL,
	"notes" text DEFAULT '' NOT NULL,
	"review_state" text DEFAULT 'needs-review' NOT NULL,
	"revision" integer DEFAULT 0 NOT NULL,
	"created_by" varchar,
	"updated_by" varchar,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payroll_profiles_worker_type_check" CHECK ("payroll_profiles"."worker_type" IN ('monthly', 'day-rate', 'contractor', 'owner-household')),
	CONSTRAINT "payroll_profiles_payment_method_check" CHECK ("payroll_profiles"."payment_method" IN ('bank-transfer', 'cash', 'third-party')),
	CONSTRAINT "payroll_profiles_review_state_check" CHECK ("payroll_profiles"."review_state" IN ('needs-review', 'reviewed')),
	CONSTRAINT "payroll_profiles_amounts_check" CHECK ("payroll_profiles"."monthly_salary" >= 0 AND "payroll_profiles"."day_rate" >= 0 AND "payroll_profiles"."fixed_fee" >= 0 AND "payroll_profiles"."food_allowance_per_day" >= 0 AND "payroll_profiles"."student_loan_monthly" >= 0),
	CONSTRAINT "payroll_profiles_percents_check" CHECK ("payroll_profiles"."pnd3_withholding_percent" BETWEEN 0 AND 100 AND "payroll_profiles"."cash_handling_fee_percent" BETWEEN 0 AND 100)
);
