CREATE TABLE IF NOT EXISTS "payroll_profile_advances" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"profile_id" uuid NOT NULL,
	"principal" numeric(14, 2) NOT NULL,
	"outstanding_balance" numeric(14, 2) NOT NULL,
	"repayment_mode" text NOT NULL,
	"instalments" integer DEFAULT 1 NOT NULL,
	"monthly_repayment" numeric(14, 2) DEFAULT '0' NOT NULL,
	"starts_on" date NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payroll_profile_advances_mode_check" CHECK ("payroll_profile_advances"."repayment_mode" IN ('one-off', 'instalments')),
	CONSTRAINT "payroll_profile_advances_amounts_check" CHECK ("payroll_profile_advances"."principal" >= 0 AND "payroll_profile_advances"."outstanding_balance" >= 0 AND "payroll_profile_advances"."outstanding_balance" <= "payroll_profile_advances"."principal" AND "payroll_profile_advances"."monthly_repayment" >= 0 AND "payroll_profile_advances"."instalments" >= 1)
);
