-- The setup audit is append-only: a row once written is never changed or removed.
CREATE OR REPLACE FUNCTION payroll_profile_changes_append_only() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
	RAISE EXCEPTION 'payroll_profile_changes is append-only (% refused)', TG_OP
		USING ERRCODE = 'restrict_violation';
END $fn$;
